from pathlib import Path
import json,argparse,hashlib,os
ap=argparse.ArgumentParser();ap.add_argument('--output',type=Path,required=True);a=ap.parse_args();assert not a.output.exists();out=a.output.with_name(a.output.name+'.pending');out.mkdir();sources=out/'source-root/ShielddSecurity';sources.mkdir(parents=True);inventory={}
def emit(n,imports,body,names):
 s='-- GENERATED by generate.py. Do not hand edit.\n'+''.join('import ShielddSecurity.'+x+'\n' for x in imports)+'set_option autoImplicit false\nset_option maxHeartbeats 900000\nset_option maxRecDepth 8192\nnoncomputable section\nnamespace ShielddSecurity.'+n+'\nopen VariableWindowLayout447 AuthorizationWindowRows455\n'+body+'\nend ShielddSecurity.'+n+'\n'
 ns=['ShielddSecurity.'+n+'.'+x for x in names];s+=''.join('\nset_option pp.all true in\n#check @'+x+'\n#print axioms '+x+'\n' for x in ns);p=sources/(n+'.lean');p.write_text(s);inventory[n]=dict(sha256=hashlib.sha256(p.read_bytes()).hexdigest(),audits=ns)
def schedule(j):
 family=j//125;window=j%125+1
 return '('+','.join(map(str,([1504,2253,2257] if family==0 else [1520,3009,3015])+[window]))+')'
header='fun b => (b.family.baseX,b.family.precomputeX,b.family.assertionStart,b.window)'
leaves=[]
for i,start in enumerate(range(0,250,8)):
 stop=min(start+8,250);n='AuthorizationCompleteWindows456B'+str(i).zfill(2);leaves.append(n);prior='VariableLayoutCapture448B'+str(i).zfill(2)
 body='def entries : List BoundEntry := '+prior+'.entries\n'
 body+='theorem checked : entries.all AuthorizationWindowRows455.check=true := by\n  apply List.all_eq_true.mpr\n  intro bound member\n  have layout := List.all_eq_true.mp '+prior+'.checked bound member\n  simp only [entries,'+prior+'.entries,List.mem_cons,List.mem_singleton,List.not_mem_nil,or_false] at member\n  rcases member with '+'|'.join('rfl' for j in range(start,stop))+'\n'
 for j in range(start,stop):
  prefix='VariableWindowCapture444B'+str(j//4).zfill(3)+'.entry'+str(j%4)
  body+='  · exact decide_eq_true ⟨layout,'+','.join(prefix+'_'+k for k in ['checked','first_checked','second_checked','addition_checked','selector_checked'])+'⟩\n'
 body+='theorem count : entries.length='+str(stop-start)+' := '+prior+'.count\n'
 body+='theorem schedule : entries.map ('+header+')=['+','.join(schedule(j) for j in range(start,stop))+'] := by decide +kernel\n'
 emit(n,['AuthorizationWindowRows455',prior],body,['entries','checked','count','schedule'])
body='def entries : List BoundEntry := '+'++'.join(x+'.entries' for x in leaves)+'\n'
body+='theorem checked : entries.all AuthorizationWindowRows455.check=true := by\n  simp only [entries,List.all_append,'+','.join(x+'.checked' for x in leaves)+',Bool.true_and]\n'
body+='theorem count : entries.length=250 := by\n  simp only [entries,List.length_append,'+','.join(x+'.count' for x in leaves)+']\n'
body+='theorem schedule : entries.map ('+header+')=['+','.join(schedule(j) for j in range(250))+'] := by\n  simp only [entries,List.map_append,'+','.join(x+'.schedule' for x in leaves)+']\n  rfl\n'
emit('AuthorizationCompleteWindows456',leaves,body,['entries','checked','count','schedule'])
(out/'generation.json').write_text(json.dumps(inventory,indent=2,sort_keys=True)+'\n');os.replace(out,a.output);print(json.dumps(dict(modules=len(inventory),windows=250)))
